## Why This Is Asked

Advanced concurrency design focusing on dynamic scaling and per-type queues, avoiding contention and starvation in a real-time analytics pipeline.

## Key Concepts

- Per-type queues and backpressure
- Dynamic worker scaling with latency feedback
- Safe shutdown and fault tolerance
- Context cancellation and coordination

## Code Example

```go
package main
import (
  "context"
  "fmt"
  "sync"
  "time"
)
type Task struct{ Type string; Payload interface{} }
func main() {
  ctx, cancel := context.WithCancel(context.Background())
  defer cancel()

  queues := map[string]chan Task{
    "CPU": make(chan Task, 100),
    "IO":  make(chan Task, 100),
  }

  var wg sync.WaitGroup
  // start workers
  for t := range queues {
    for i := 0; i < 2; i++ {
      wg.Add(1)
      go worker(ctx, t, queues[t], &wg)
    }
  }

  // simple enqueue
  queues["CPU"] <- Task{Type: "CPU"}
  queues["IO"] <- Task{Type: "IO"}

  time.Sleep(100 * time.Millisecond)
  cancel()
  for _, ch := range queues { close(ch) }
  wg.Wait()
}
func worker(ctx context.Context, t string, ch <-chan Task, wg *sync.WaitGroup) {
  defer wg.Done()
  for {
    select {
    case <-ctx.Done():
      return
    case task, ok := <-ch:
      if !ok { return }
      time.Sleep(10 * time.Millisecond)
      fmt.Println("done", t)
    }
  }
}
```

